CREATE TABLE competitions (id UUID PRIMARY KEY,title VARCHAR(120) NOT NULL,description TEXT,cover_url VARCHAR(500),competition_type VARCHAR(20) NOT NULL,event_type VARCHAR(20) NOT NULL,format VARCHAR(30) NOT NULL,status VARCHAR(30) NOT NULL,registration_scope VARCHAR(20) NOT NULL,registration_requires_review BOOLEAN NOT NULL,max_participants INTEGER NOT NULL,best_of INTEGER NOT NULL,points_per_game INTEGER NOT NULL DEFAULT 11,strict_score_validation BOOLEAN NOT NULL DEFAULT TRUE,location VARCHAR(200) NOT NULL,registration_start TIMESTAMPTZ,registration_end TIMESTAMPTZ,start_time TIMESTAMPTZ,end_time TIMESTAMPTZ,creator_user_id UUID NOT NULL REFERENCES users(id),rating_rule_version VARCHAR(20),arrangement_seed BIGINT,version BIGINT NOT NULL DEFAULT 0,created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX idx_competitions_status_start ON competitions(status,start_time); CREATE INDEX idx_competitions_type ON competitions(competition_type);
CREATE TABLE competition_entries (id UUID PRIMARY KEY,competition_id UUID NOT NULL REFERENCES competitions(id),user_id UUID NOT NULL REFERENCES users(id),status VARCHAR(20) NOT NULL,seed_number INTEGER,registered_at TIMESTAMPTZ NOT NULL,approved_at TIMESTAMPTZ,created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE(competition_id,user_id));
CREATE INDEX idx_competition_entries_competition_status ON competition_entries(competition_id,status); CREATE INDEX idx_competition_entries_user ON competition_entries(user_id);
